<script setup>
import { onMounted } from 'vue'; import { useRoute, useRouter } from 'vue-router'; import { useAutopeer } from '../../state/autopeer';
const s=useAutopeer(),route=useRoute(),router=useRouter(); onMounted(async()=>{if(!s.currentUser.value)await s.bootstrap();if(route.params.asn){const x=s.sessions.value.find(v=>v.node.id===route.params.node&&String(v.peer.asn)===String(route.params.asn));s.resetForm(x||null,s.nodes.value.find(n=>n.id===route.params.node))}else s.resetForm(null,s.nodes.value.find(n=>n.id===route.params.node))})
</script>
<template><section class="wizard-page"><mdui-button variant="text" @click="router.back()">← Back</mdui-button><p class="eyebrow">{{s.form.mode==='edit'?'EDIT':'NEW'}} PEERING</p><h1>{{s.form.mode==='edit'?'Edit':'Start peering'}} on {{s.form.node}}</h1><div class="wizard-steps"><span :class="{active:s.wizardStep.value>=1}">1. Session</span><span :class="{active:s.wizardStep.value>=2}">2. Interface</span><span :class="{active:s.wizardStep.value>=3}">3. Confirm</span></div><section v-if="s.wizardStep.value===1" class="wizard-panel"><mdui-text-field label="Contact information" :value="s.form.contact" @input="s.form.contact=$event.target.value"/><mdui-text-field v-if="s.isAdmin.value&&s.form.mode==='create'" label="Peer ASN" type="number" :value="s.form.asn" @input="s.form.asn=$event.target.value"/></section><section v-else-if="s.wizardStep.value===2" class="wizard-panel"><mdui-text-field label="Public key" :value="s.form.publicKey" @input="s.form.publicKey=$event.target.value"/><mdui-text-field label="Endpoint" :value="s.form.endpoint" @input="s.form.endpoint=$event.target.value"/><mdui-text-field label="Link MTU" type="number" :value="s.form.mtu" @input="s.form.mtu=$event.target.value"/><mdui-text-field label="IPv4 address" :value="s.form.ipv4Address" @input="s.form.ipv4Address=$event.target.value"/><mdui-text-field label="IPv6 link-local address" :value="s.form.ipv6LinkLocalAddress" @input="s.form.ipv6LinkLocalAddress=$event.target.value"/></section><section v-else class="wizard-panel"><h2>Confirm peering request</h2><p>Node: {{s.form.node}} · Contact: {{s.form.contact}}</p><p>Endpoint: {{s.form.endpoint}}</p></section><div class="wizard-page-actions"><mdui-button variant="outlined" @click="s.wizardStep.value>1?s.wizardStep.value--:router.back()">Back</mdui-button><mdui-button v-if="s.wizardStep.value<3" variant="filled" @click="s.nextWizardStep()">Continue</mdui-button><mdui-button v-else variant="filled" :loading="s.saving.value" @click="s.saveSession">Confirm and queue</mdui-button></div></section></template>